// src/services/studentService.js
const BASE = 'http://localhost:4000/students';

export function getStudents() {
  return fetch(BASE).then(r => {
    if (!r.ok) throw new Error('Failed to fetch students');
    return r.json();
  });
}

export function getStudent(id) {
  return fetch(`${BASE}/${id}`).then(r => {
    if (!r.ok) throw new Error('Failed to fetch student');
    return r.json();
  });
}

export function addStudent(data) {
  return fetch(BASE, {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify(data)
  }).then(r => {
    if (!r.ok) throw new Error('Failed to add student');
    return r.json();
  });
}

export function updateStudent(id, data) {
  return fetch(`${BASE}/${id}`, {
    method: 'PUT',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify(data)
  }).then(r => {
    if (!r.ok) throw new Error('Failed to update student');
    return r.json();
  });
}

export function deleteStudent(id) {
  return fetch(`${BASE}/${id}`, { method: 'DELETE' }).then(r => {
    if (!r.ok) throw new Error('Failed to delete student');
    return r;
  });
}
